    public static string Get(string key, params object[] args)
    {
        if (!Table.TryGetValue(key, out var pair)) return $"[{key}]";
        var s = Es ? pair.es : pair.en;
        return args.Length > 0 ? string.Format(s, args) : s;
    }
}
